class Elevator:
    def __init__(self, floor=0):
        self.floor = floor
        self.state = "IDLE"
        self.direction = "up"
        self.stops = []
        self.served = []
        self.travelled = 0

    def call(self, floor):
        if floor not in self.stops:
            self.stops.append(floor)

    def _target(self):
        if not self.stops:
            return None
        ahead = [s for s in self.stops if (s >= self.floor if self.direction == "up" else s <= self.floor)]
        if not ahead:
            self.direction = "down" if self.direction == "up" else "up"
            ahead = self.stops
        return min(ahead, key=lambda s: abs(s - self.floor))

    def tick(self):
        if self.state == "DOORS_OPEN":
            self.state = "IDLE"
            return self.state
        t = self._target()
        if t is None:
            self.state = "IDLE"
        elif t == self.floor:
            self.stops.remove(t)
            self.served.append(t)
            self.state = "DOORS_OPEN"
        elif t > self.floor:
            self.floor += 1
            self.travelled += 1
            self.state = "MOVING_UP"
        else:
            self.floor -= 1
            self.travelled += 1
            self.state = "MOVING_DOWN"
        return self.state

def tokenize(src):
    tokens = []
    i = 0
    while i < len(src):
        c = src[i]
        if c == " ":
            i += 1
        elif c.isdigit() or c == ".":
            j = i
            while j < len(src) and (src[j].isdigit() or src[j] == "."):
                j += 1
            tokens.append(float(src[i:j]))
            i = j
        elif c in "+-*/^()":
            tokens.append(c)
            i += 1
        else:
            raise ValueError(f"unexpected character {c!r} at position {i}")
    return tokens

