def base62(n):
    out = ""
    while n:
        n, r = divmod(n, 62)
        out = DIGITS[r] + out
    return out or "0"

class Shortener:
    def __init__(self, kv):
        self.kv = kv

    def shorten(self, url):
        n = int(self.kv.get("#next") or 1)
        code = base62(n)
        self.kv.set(code, url)
        self.kv.set("#next", n + 1)
        return code

    def resolve(self, code):
        return self.kv.get(code)

