class Catalogue:
    def __init__(self):
        self.root = bt_node()

    def add(self, row):
        self.root = bt_insert(self.root, row["id"], row)

    def get(self, id):
        node = self.root
        while True:
            i = bisect.bisect_left(node["keys"], id)
            if i < len(node["keys"]) and node["keys"][i] == id:
                return node["vals"][i]
            if not node["kids"]:
                return None
            node = node["kids"][i]

    def between(self, lo, hi):
        out = []
        def walk(node):
            keys = node["keys"]
            for i, k in enumerate(keys):
                if node["kids"] and lo < k:
                    walk(node["kids"][i])
                if lo <= k <= hi:
                    out.append(node["vals"][i])
                if k > hi:
                    return
            if node["kids"] and keys[-1] < hi:
                walk(node["kids"][-1])
        walk(self.root)
        return out

