from collections import deque
def merge_base(parents, a, b):
    seen, stack = set(), [a]
    while stack:
        c = stack.pop()
        if c not in seen:
            seen.add(c)
            stack.extend(parents[c])
    queue, visited = deque([b]), set()
    while queue:
        c = queue.popleft()
        if c in seen:
            return c
        if c not in visited:
            visited.add(c)
            queue.extend(parents[c])
    return None

