def satisfy(pts, rest, iters=20):
    pts = pts.copy()
    for _ in range(iters):
        for i in range(len(pts) - 1):
            d = pts[i + 1] - pts[i]
            L = np.linalg.norm(d)
            if L == 0:
                continue
            fix = (L - rest) / L * d
            if i == 0:
                pts[i + 1] -= fix
            else:
                pts[i] += fix / 2
                pts[i + 1] -= fix / 2
    return pts

