def train_step(net, xs, ys, lr):
    loss = sum(((net(x) - y) ** 2 for x, y in zip(xs, ys)), Value(0.0)) * (1 / len(xs))
    for p in net.parameters():
        p.grad = 0.0
    loss.backward()
    for p in net.parameters():
        p.data -= lr * p.grad
    return loss.data

def fit_linear(rows, ys, steps=500, lr=0.1):
    ws = [Value(0.0) for _ in rows[0]]
    b = Value(0.0)
    params = ws + [b]
    for _ in range(steps):
        loss = Value(0.0)
        for x, y in zip(rows, ys):
            pred = sum((w * xi for w, xi in zip(ws, x)), b)
            loss = loss + (pred - y) ** 2
        loss = loss * (1 / len(rows))
        for p in params:
            p.grad = 0.0
        loss.backward()
        for p in params:
            p.data -= lr * p.grad
    return [w.data for w in ws], b.data

