OPS = {"HALT": 0, "LOADI": 1, "ADD": 2, "SUB": 3, "JNZ": 4, "OUT": 5}

def assemble(text):
    lines = [l.strip() for l in text.splitlines() if l.strip()]
    labels, addr = {}, 0
    for line in lines:
        if line.endswith(":"):
            labels[line[:-1]] = addr
        else:
            addr += 2 if line.split()[0] in ("LOADI", "JNZ") else 1
    out = []
    for line in lines:
        if line.endswith(":"):
            continue
        name, _, rest = line.partition(" ")
        args = [a.strip() for a in rest.split(",") if a.strip()]
        regs = [int(a[1:]) for a in args if a.startswith("r")]
        regs += [0] * (2 - len(regs))
        out.append(OPS[name] << 4 | regs[0] << 2 | regs[1])
        if name == "LOADI":
            out.append(int(args[1]))
        elif name == "JNZ":
            out.append(labels[args[1]])
    return out

